// Differential tests for the npps binary arithmetic families
// (nppsAdd / nppsSub / nppsMul / nppsDiv / nppsDiv_Round / nppsAddProduct).
// GENERATED by mpp_scripts/gen_binary_diff_tests.py.
//
// A _Ctx case and its plain entry point share one case id so the 5090 recorded
// golden is validated against both MPP entry points.  Integers are compared
// exactly; floats use rtol=atol=1e-5.

#include "npp_diff_harness.h"
#include "npp_test_base.h"

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

using namespace npp_diff;
using namespace npp_functional_test;

namespace {

NppStreamContext current_context() {
  NppStreamContext ctx{};
  NppStatus st = nppGetStreamContext(&ctx);
  EXPECT_EQ((int)st, (int)NPP_NO_ERROR) << "nppGetStreamContext failed";
  return ctx;
}

void out2(Case &c, const void *dst, size_t count, ValueKind kind, double rtol = 1e-5, double atol = 1e-5) {
  if (count > 0 && dst != nullptr) c.device_output(static_cast<const Npp8u *>(dst), count, kind, rtol, atol);
}

template <typename T> std::vector<T> make_vec(size_t n, uint64_t s) {
  std::vector<T> v(n); Rng r(s);
  for (auto &x : v) {
    if constexpr (std::is_same_v<T, float> || std::is_same_v<T, double>) x = static_cast<T>(r.unit_double() * 4.0 - 2.0);
    else x = static_cast<T>(r.integer<uint64_t>(0, ~0ULL));
  }
  return v;
}
std::vector<Npp16sc> v16(size_t n, uint64_t s) { std::vector<Npp16sc> v(n); Rng r(s); for (auto &x : v) { x.re = r.integer<Npp16s>(-1000, 1000); x.im = r.integer<Npp16s>(-1000, 1000); } return v; }
std::vector<Npp32sc> v32(size_t n, uint64_t s) { std::vector<Npp32sc> v(n); Rng r(s); for (auto &x : v) { x.re = r.integer<Npp32s>(-100000, 100000); x.im = r.integer<Npp32s>(-100000, 100000); } return v; }
std::vector<Npp32fc> vfc(size_t n, uint64_t s)  { std::vector<Npp32fc> v(n); Rng r(s); for (auto &x : v) { x.re = r.unit_float() * 4.f - 2.f; x.im = r.unit_float() * 4.f - 2.f; } return v; }
std::vector<Npp64fc> vfc64(size_t n, uint64_t s){ std::vector<Npp64fc> v(n); Rng r(s); for (auto &x : v) { x.re = r.unit_double() * 4.0 - 2.0; x.im = r.unit_double() * 4.0 - 2.0; } return v; }

void finish_case(const char *id, const char *fn, NppStatus st, const void *dst, size_t count,
                 ValueKind kind, double rtol = 1e-5, double atol = 1e-5) {
  Case c(id, fn);
  c.status(st);
  out2(c, dst, count, kind, rtol, atol);
  c.finish();
}

} // namespace

class NppsBinaryArithmetic : public ::testing::Test {
protected:
  void TearDown() override { (void)cudaDeviceSynchronize(); }
};

// MARKER

TEST_F(NppsBinaryArithmetic, nppsAdd_8u_Sfs_Ctx) {
  const NppSignalLength n = 257;
  std::vector<uint8_t> a = make_vec<uint8_t>(n,43066857981397319);
  std::vector<uint8_t> b = make_vec<uint8_t>(n,15331936606189407);
  std::vector<uint8_t> d = make_vec<uint8_t>(n,15596952417376998);
  DeviceMemory<uint8_t> da(n); da.copyFromHost(a);
  DeviceMemory<uint8_t> db(n); db.copyFromHost(b);
  DeviceMemory<uint8_t> dc(n); dc.copyFromHost(d);
  clear_cuda_error();
  NppStatus st = nppsAdd_8u_Sfs_Ctx(da.get(), db.get(), dc.get(), n, 4, current_context());
  finish_case("nppsBinary/nppsAdd/nppsAdd_8u_Sfs", "nppsAdd_8u_Sfs_Ctx", st, dc.get(), 257, ValueKind::U8, 0, 0);
}
